<script setup>
const route = useRoute();
const refCode = computed(() => String(route.query.ref || '').trim().toUpperCase().slice(0, 20));
const { data, error, refresh } = await useApiFetch(() => `/api/billing/config${refCode.value ? `?ref=${encodeURIComponent(refCode.value)}` : ''}`, { key: `billing-config:${String(route.query.ref || 'none').toUpperCase()}`, default: () => null });
const config = computed(() => data.value);
const tiers = computed(() => config.value?.catalog?.tiers || []);
const referral = computed(() => config.value?.referral || null);
const currentPlan = computed(() => config.value?.plan?.plan || 'free');
const interval = ref(route.query.ref ? 'monthly' : 'yearly');
watch(config, c => { if (c?.catalog?.defaultInterval) interval.value = route.query.ref ? 'monthly' : c.catalog.defaultInterval; }, { immediate: true });
const cycles = computed(() => tiers.value[0]?.intervals || []);
const openTier = ref(null);
const modalTier = computed(() => tiers.value.find(t => t.key === openTier.value) || null);
const features = [{ name: 'Replay library', free: 'None', plus: '10 replays / 7 days', pro: '100 replays / 30 days' }, { name: 'Replay length', free: 'None', plus: 'Up to 15 minutes', pro: 'Up to 60 minutes' }, { name: 'Movement stats', free: 'Basic', plus: 'All available stats', pro: 'All available stats' }, { name: 'Profile cards', free: 'Basic', plus: 'More themes and fonts', pro: 'All customization' }, { name: 'Upcoming code preview', free: 'None', plus: 'None', pro: '15 minutes before rotation' }, { name: 'Queue priority', free: 'Standard', plus: 'Priority', pro: 'Priority' }, { name: 'Friend leaderboard', free: 'None', plus: 'Included', pro: 'Included' }, { name: 'Practice matches', free: '1 per day', plus: '3 per day', pro: '10 per day' }, { name: 'Bot difficulty', free: 'Up to Average', plus: 'Up to Good', pro: 'Up to Best' }, { name: 'Training categories (coming soon)', free: 'Basic', plus: 'Advanced + cut offs', pro: 'All categories' }, { name: 'Match history', free: '25 matches', plus: 'Unlimited', pro: 'Unlimited' }];
useSeo({ title: 'Membership: Plus and Pro', description: 'Compare Free, Plus and Pro on Ranked World. Replays, movement stats, profile card themes, practice matches per day, bot difficulty and match history.' });
</script>
<template>
<main id="main" class="wrap section world-subscribe"><div class="world-page-title"><h1>Membership</h1><NuxtLink v-if="config?.signedIn" class="world-back" to="/settings#membership">Manage subscription<AppIcon name="arrowRight" /></NuxtLink></div><div v-if="error" class="world-error" role="alert"><p>Could not load plans.</p><button class="btn" @click="refresh">Try again</button></div><template v-else-if="config?.catalog"><p v-if="referral && referral.eligible" class="world-referral-note" role="status"><strong>{{ referral.code }} applied</strong> - {{ referral.percent }}% off your first month on monthly billing. Later months renew at the regular price.</p><p v-else-if="referral" class="world-referral-note world-referral-note--muted" role="status"><strong>{{ referral.code }}</strong> gives {{ referral.percent }}% off a first monthly subscription. It does not apply to your account.</p><div class="world-billing-controls"><span>Billing cycle</span><div class="world-billing-tabs" aria-label="Billing cycle"><button v-for="cycle in cycles" :key="cycle.key" :aria-pressed="interval === cycle.key" @click="interval = cycle.key">{{ cycle.label }}</button></div></div><div class="world-plans"><section class="world-plan world-plan--free"><div class="world-plan-heading"><h2>Free</h2><span v-if="currentPlan === 'free' && config.signedIn" class="chip">Current plan</span></div><p class="world-plan-price"><strong>$0</strong><span>/ month</span></p><p class="meta world-plan-billing">No subscription required</p><NuxtLink class="btn" to="/play">Play ranked<AppIcon name="arrowRight" /></NuxtLink><ul class="world-plan-features"><li>Ranked codes and leaderboards</li><li>1 practice match per day</li><li>Basic training categories</li><li>Last 25 matches</li></ul></section><PlusPlanCard v-for="tier in tiers" :key="tier.key" :tier="tier" :interval="interval" :configured="config.configured" :signed-in="config.signedIn" :current-plan="currentPlan" :referral="referral" @subscribe="openTier = $event" /></div><p class="world-billing-note">Prices in USD. Cancel anytime.<span v-if="!config.configured"> Paid subscriptions are not available yet.</span></p><section class="world-plan-comparison"><div class="world-section-head"><h2>Compare plans</h2></div><div class="world-table-scroll" role="region" aria-label="Membership comparison" tabindex="0"><table class="world-table"><thead><tr><th>Included</th><th>Free</th><th>Plus</th><th>Pro</th></tr></thead><tbody><tr v-for="feature in features" :key="feature.name"><th scope="row">{{ feature.name }}</th><td>{{ feature.free }}</td><td>{{ feature.plus }}</td><td>{{ feature.pro }}</td></tr></tbody></table></div></section><details class="world-plan-details"><summary>All membership benefits</summary><div class="world-benefit-columns"><section v-for="tier in [config.catalog.free, ...tiers]" :key="tier.key"><h3>{{ tier.name }}</h3><p v-if="tier.key !== 'free'" class="meta">{{ tier.key === 'plus' ? 'Includes Free benefits' : 'Includes Plus benefits' }}</p><ul><li v-for="perk in tier.perks" :key="perk">{{ perk }}</li></ul></section></div></details></template><div v-else class="world-empty" role="status">Loading plans...</div><PlusCheckoutModal :open="Boolean(openTier)" :tier="modalTier" :interval="interval" :publishable-key="config?.publishableKey || ''" @close="openTier = null" /></main>
</template>
<style src="~/assets/css/subscribe.css">
</style>
